'use client';

import * as React from 'react';
import { Sparkles } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { generateStrategy, type StrategyRequest } from '@/lib/api';

export default function ViralytiqDashboardPage() {
  const [topic, setTopic] = React.useState(
    'Cutting pgvector RAG P95 latency under 200ms with Groq Llama 3.3'
  );

  const [pillar, setPillar] =
    React.useState<StrategyRequest['pillar']>('Technical Deep-Dive');

  const [loading, setLoading] = React.useState(false);

  const [draft, setDraft] = React.useState({
    hook:
      'Everyone talks about LLM reasoning.\nAlmost nobody measures retrieval tail latency.',
    body:
      'Three architectural changes brought our P95 RAG latency to 184ms using pgvector HNSW and Groq.',
    cta: 'Where is the hidden latency hiding in your AI stack right now?',
    viralityScore: 94,
  });

  const [traces, setTraces] = React.useState<
    Array<{ label: string; durationMs: number; status: string }>
  >([
    { label: 'Research Agent', durationMs: 1200, status: 'completed' },
    { label: 'Brand Agent', durationMs: 800, status: 'completed' },
    { label: 'Writing Agent', durationMs: 2100, status: 'completed' },
    { label: 'Reviewer Agent', durationMs: 700, status: 'completed' },
  ]);

  const handleRun = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const data = await generateStrategy({
        topic,
        pillar,
        format: 'Text + Hook',
        tone: 'Direct & Analytical',
        targetAudience: 'Seed-Series B SaaS Founders & Staff Engineers',
        useVoiceRag: true,
      });

      if (data?.post) {
        setDraft({
          hook: data.post.hook ?? draft.hook,
          body: data.post.body ?? draft.body,
          cta: data.post.cta ?? draft.cta,
          viralityScore: data.post.viralityScore ?? draft.viralityScore,
        });
      }
      if (Array.isArray(data?.traces) && data.traces.length > 0) {
        setTraces(
          data.traces.map(
            (t: { label?: string; durationMs?: number; status?: string }) => ({
              label: t.label ?? 'Agent',
              durationMs: t.durationMs ?? 0,
              status: t.status ?? 'completed',
            })
          )
        );
      }
    } catch {
      setDraft({
        hook: 'Most teams over-engineer retrieval.\nThe real edge is speed.',
        body:
          'Optimized RAG architectures consistently outperform larger models with poor retrieval.',
        cta: 'What bottleneck surprised you most in production?',
        viralityScore: 89,
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <div className="mb-8">
        <h1 className="text-3xl font-bold md:text-4xl">AI Content Strategy Studio</h1>
        <p className="mt-2 text-slate-400">
          Create high-performing LinkedIn content powered by Agents, RAG, LangGraph and Groq.
        </p>
      </div>

      <div className="mb-8 grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-4">
        <Card>
          <p className="text-sm text-slate-400">Brand Score</p>
          <h3 className="mt-2 text-4xl font-bold">92</h3>
        </Card>
        <Card>
          <p className="text-sm text-slate-400">Virality Score</p>
          <h3 className="mt-2 text-4xl font-bold text-indigo-300">{draft.viralityScore}</h3>
        </Card>
        <Card>
          <p className="text-sm text-slate-400">Knowledge Chunks</p>
          <h3 className="mt-2 text-4xl font-bold">1432</h3>
        </Card>
        <Card>
          <p className="text-sm text-slate-400">AI Confidence</p>
          <h3 className="mt-2 text-4xl font-bold text-green-400">97%</h3>
        </Card>
      </div>

      <div className="grid gap-6 lg:grid-cols-2">
        <Card>
          <h2 className="mb-5 text-xl font-semibold">Content Generator</h2>
          <form onSubmit={handleRun} className="space-y-5">
            <div>
              <label className="mb-2 block text-sm text-slate-300">Topic</label>
              <input
                value={topic}
                onChange={(e) => setTopic(e.target.value)}
                className="w-full rounded-xl border border-white/10 bg-white/5 px-4 py-3 outline-none focus:border-indigo-500/50"
              />
            </div>
            <div>
              <label className="mb-2 block text-sm text-slate-300">Content Pillar</label>
              <select
                value={pillar}
                onChange={(e) => setPillar(e.target.value as StrategyRequest['pillar'])}
                className="w-full rounded-xl border border-white/10 bg-white/5 px-4 py-3 outline-none focus:border-indigo-500/50"
              >
                <option value="Technical Deep-Dive">Technical Deep-Dive</option>
                <option value="Founder Lessons">Founder Lessons</option>
                <option value="Contrarian Take">Contrarian Take</option>
                <option value="Product Breakdown">Product Breakdown</option>
              </select>
            </div>
            <Button type="submit" disabled={loading}>
              <Sparkles className="h-4 w-4" />
              {loading ? 'Generating...' : 'Generate Strategy'}
            </Button>
          </form>
        </Card>

        <Card>
          <h2 className="mb-5 text-xl font-semibold">LinkedIn Draft Preview</h2>
          <p className="whitespace-pre-line text-xl font-bold">{draft.hook}</p>
          <p className="mt-6 leading-8 whitespace-pre-line text-slate-300">{draft.body}</p>
          <p className="mt-6 font-semibold text-indigo-300">{draft.cta}</p>
        </Card>
      </div>

      <Card className="mt-8">
        <h2 className="mb-6 text-xl font-semibold">Agent Execution Trace</h2>
        <div className="grid gap-4 md:grid-cols-2">
          {traces.map((t) => (
            <div
              key={t.label}
              className="flex items-center justify-between rounded-xl bg-white/5 p-4"
            >
              <span>{t.label}</span>
              <span className="text-green-400">
                {t.status === 'completed' ? '✅' : '…'} {(t.durationMs / 1000).toFixed(1)}s
              </span>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}